#!/usr/bin/env python3
import html
import re
import sys

ESCAPABLE = r'!"#$%&\'()*+,-./:;<=>?@[\\]^_`{|}~'
INLINE_TAGS = re.compile(r'<(?:[A-Za-z][A-Za-z0-9+.-]{1,31}:[^ >]+|[A-Za-z][^ >]*@[^ >]+|/?[A-Za-z][^>]*|!--[\s\S]*?--|\?[\s\S]*?\?|![A-Z]+\s+[\s\S]*?\s*!|![CDATA\[[\s\S]*?\]\])>')

def esc_text(s):
    return html.escape(s, quote=False)

def normalize_source(s):
    s = s.replace('\r\n', '\n').replace('\r', '\n').replace('\x00', '\ufffd')
    # Tabs are expanded to tab stops during block parsing.
    expanded=[]
    for line in s.splitlines():
        col=0; result=''
        for ch in line:
            if ch=='\t':
                spaces=4-(col%4); result+=' '*spaces; col+=spaces
            else: result+=ch; col+=1
        expanded.append(result)
    return '\n'.join(expanded) + ('\n' if not s.endswith('\n') else '')

class Document:
    def __init__(self, source):
        self.lines = normalize_source(source).splitlines()
        self.refs = {}

    def parse(self):
        self.collect_refs()
        return self.blocks(self.lines)

    def collect_refs(self):
        out=[]; i=0
        while i < len(self.lines):
            m=re.match(r' {0,3}\[([^\]]+)\]:[ \t]*(?:<([^>]+)>|(\S+))(?:[ \t]+(?:"([^"]*)"|\'([^\']*)\'|\(([^)]*)\)))?[ \t]*$', self.lines[i])
            if m:
                self.refs[m.group(1).strip().casefold()] = (m.group(2) or m.group(3), m.group(4) or m.group(5) or m.group(6))
                i+=1; continue
            out.append(self.lines[i]); i+=1
        self.lines=out

    def inline(self, text):
        text = text.replace('\\\n','<br />\n')
        stash=[]
        def hold(v): stash.append(v); return f'\x00{len(stash)-1}\x00'
        # protect code spans, raw HTML, and autolinks before escaping
        def code(m):
            x=m.group(2).replace('\n',' ')
            if x.startswith(' ') and x.endswith(' ') and x.strip(): x=x[1:-1]
            return hold('<code>'+esc_text(x)+'</code>')
        text=re.sub(r'(`+)([\s\S]*?)\1',code,text)
        def raw(m):
            tag=m.group(0)
            if re.match(r'<[A-Za-z][A-Za-z0-9+.-]{1,31}:',tag):
                u=tag[1:-1]; return hold('<a href="'+html.escape(u,quote=True)+'">'+esc_text(u.removeprefix('mailto:'))+'</a>')
            if re.match(r'<[^ <>]+@[^ <>]+>',tag):
                u=tag[1:-1]; return hold('<a href="mailto:'+html.escape(u,quote=True)+'">'+esc_text(u)+'</a>')
            return hold(tag)
        text=INLINE_TAGS.sub(raw,text)
        text=html.escape(html.unescape(text),quote=True)
        text=re.sub(r'\\([!"#$%&\'()*+,\-./:;<=>?@\[\\\]^_`{|}~])',r'\1',text)
        text=re.sub(r'&amp;(#(?:x[0-9A-Fa-f]+|[0-9]+)|[A-Za-z][A-Za-z0-9]+);',lambda m:'&'+m.group(1)+';',text)
        # images and links, including reference forms
        def image(m):
            alt= re.sub(r'[*_`]','',m.group(1)); dest=m.group(2); title=m.group(3)
            a='<img src="'+html.escape(dest,quote=True)+'" alt="'+html.escape(alt,quote=True)+'"'
            if title is not None: a+=' title="'+html.escape(title,quote=True)+'"'
            return a+' />'
        def link(m):
            label=m.group(1); dest=m.group(2); title=m.group(3)
            a='<a href="'+html.escape(dest,quote=True)+'"'
            if title is not None: a+=' title="'+html.escape(title,quote=True)+'"'
            return a+'>'+self.inline(label)+'</a>'
        text=re.sub(r'!\[([^\]]*)\]\((?:<([^>]+)>|(\S+?))(?:\s+(?:"([^"]*)"|\'([^\']*)\'|\(([^)]*)\)))?\)',lambda m:image(type('M',(),{'group':lambda _,n: [None,m.group(1),m.group(2) or m.group(3),m.group(4) or m.group(5) or m.group(6)][n]})()),text)
        text=re.sub(r'\[([^\]]+)\]\((?:<([^>]+)>|(\S+?))(?:\s+(?:"([^"]*)"|\'([^\']*)\'|\(([^)]*)\)))?\)',lambda m:link(type('M',(),{'group':lambda _,n: [None,m.group(1),m.group(2) or m.group(3),m.group(4) or m.group(5) or m.group(6)][n]})()),text)
        def ref(m):
            key=(m.group(2) or m.group(1)).strip().casefold(); r=self.refs.get(key)
            if not r:return m.group(0)
            if m.group(0).startswith('!'):
                return '<img src="'+html.escape(r[0],quote=True)+'" alt="'+html.escape(m.group(1),quote=True)+'"'+((' title="'+html.escape(r[1],quote=True)+'"') if r[1] else '')+' />'
            return '<a href="'+html.escape(r[0],quote=True)+'"'+((' title="'+html.escape(r[1],quote=True)+'"') if r[1] else '')+'>'+self.inline(m.group(1))+'</a>'
        def replace_ref(m):
            key=(m.group(3) or m.group(2)).strip().casefold()
            if key not in self.refs: return m.group(0)
            url,title=self.refs[key]
            if m.group(1):
                return '<img src="'+html.escape(url,quote=True)+'" alt="'+html.escape(m.group(2),quote=True)+'"'+((' title="'+html.escape(title,quote=True)+'"') if title else '')+' />'
            return '<a href="'+html.escape(url,quote=True)+'"'+((' title="'+html.escape(title,quote=True)+'"') if title else '')+'>'+self.inline(m.group(2))+'</a>'
        text=re.sub(r'(!?)\[([^\]]+)\](?:\[([^\]]*)\])?',replace_ref,text)
        # emphasis (delimiters are intentionally conservative)
        text=re.sub(r'\*\*([^*\n]+)\*\*|__([^_\n]+)__',lambda m:'<strong>'+self.inline(m.group(1) or m.group(2))+'</strong>',text)
        text=re.sub(r'(?<!\w)\*([^*\n]+)\*|(?<!\w)_([^_\n]+)_(?!\w)',lambda m:'<em>'+self.inline(m.group(1) or m.group(2))+'</em>',text)
        text=re.sub(r' {2,}\n','<br />\n',text)
        for i,v in enumerate(stash): text=text.replace(f'\x00{i}\x00',v)
        return text

    def blocks(self, lines):
        out=[]; i=0; n=len(lines)
        while i<n:
            line=lines[i]
            if not line.strip(): i+=1; continue
            m=re.match(r' {0,3}(`{3,}|~{3,})\s*([^`]*)$',line)
            if m:
                fence=m.group(1); info=m.group(2).strip(); body=[]; i+=1
                while i<n and not re.match(r' {0,3}'+re.escape(fence[0])+r'{'+str(len(fence))+r',}\s*$',lines[i]): body.append(lines[i]); i+=1
                if i<n:i+=1
                cls=' class="language-'+html.escape(info.split()[0],quote=True)+'"' if info else ''
                out.append('<pre><code'+cls+'>'+esc_text('\n'.join(body)+('\n' if body else ''))+'</code></pre>'); continue
            m=re.match(r' {0,3}(#{1,6})(?:[ \t]+|$)(.*)$',line)
            if m:
                content=re.sub(r'[ \t]+#+[ \t]*$','',m.group(2)); out.append(f'<h{len(m.group(1))}>'+self.inline(content)+f'</h{len(m.group(1))}>'); i+=1; continue
            if re.match(r' {0,3}((\*\s*){3,}|(-\s*){3,}|(_\s*){3,})$',line): out.append('<hr />'); i+=1; continue
            if re.match(r' {0,3}>',line):
                q=[]
                while i<n and (re.match(r' {0,3}>',lines[i]) or not lines[i].strip()):
                    q.append(re.sub(r'^ {0,3}>[ \t]?','',lines[i])); i+=1
                out.append('<blockquote>\n'+self.blocks(q)+'\n</blockquote>'); continue
            lm=re.match(r' {0,3}([-+*]|\d+[.)])[ \t]+(.*)$',line)
            if lm:
                marker=lm.group(1); ordered=marker[0].isdigit(); items=[]
                while i<n:
                    mm=re.match(r' {0,3}([-+*]|\d+[.)])[ \t]+(.*)$',lines[i])
                    if not mm or mm.group(1)[0].isdigit()!=ordered: break
                    item=[mm.group(2)]; i+=1
                    while i<n and lines[i].strip() and not re.match(r' {0,3}([-+*]|\d+[.)])[ \t]+',lines[i]):
                        item.append(re.sub(r'^ {2,4}','',lines[i])); i+=1
                    items.append(item)
                tag='ol' if ordered else 'ul'; attrs=''
                if ordered and not marker.startswith('1'): attrs=' start="'+re.match(r'\d+',marker).group()+'"'
                rendered=[]
                for item in items:
                    content=self.blocks(item).strip()
                    if content.startswith('<p>') and content.endswith('</p>') and '\n' not in content:
                        content=content[3:-4]
                    rendered.append('<li>'+content+'</li>')
                out.append('<'+tag+attrs+'>'+''.join(rendered)+'</'+tag+'>'); continue
            if re.match(r' {4}',line):
                b=[]
                while i<n and (lines[i].startswith('    ') or not lines[i].strip()): b.append(lines[i][4:] if lines[i].startswith('    ') else ''); i+=1
                out.append('<pre><code>'+esc_text('\n'.join(b).rstrip('\n')+'\n')+'</code></pre>'); continue
            # HTML blocks
            if re.match(r' {0,3}<(?:script|pre|style|div|table|ul|ol|h[1-6]|p|address|article|section|details|summary|blockquote|hr|!--|!DOCTYPE|\?|!\[CDATA\[)',line,re.I):
                b=[line]; i+=1
                while i<n and lines[i].strip(): b.append(lines[i]); i+=1
                out.append('\n'.join(b)); continue
            # paragraph, with setext heading
            b=[line]; i+=1
            while i<n and lines[i].strip():
                if re.match(r' {0,3}(#{1,6})[ \t]| {0,3}(`{3,}|~{3,})| {0,3}>| {4}',lines[i]): break
                if re.match(r' {0,3}(=+|-+)[ \t]*$',lines[i]) and len(b)==1:
                    out.append('<h1>'+self.inline(b[0].strip())+'</h1>' if lines[i].lstrip().startswith('=') else '<h2>'+self.inline(b[0].strip())+'</h2>'); i+=1; b=None; break
                b.append(lines[i]); i+=1
            if b is not None: out.append('<p>'+self.inline('\n'.join(b))+'</p>')
        return '\n'.join(out)+'\n' if out else ''

def main():
    sys.stdout.write(Document(sys.stdin.read()).parse())
if __name__=='__main__': main()
